async function processPendingMinimums() {
  if (!await isPoolEnabled()) return 0;
  let paidCount = 0;
  try {
    const pending = await db.select().from(poolPendingMinimumsTable).where(eq(poolPendingMinimumsTable.status, "pending")).orderBy(asc(poolPendingMinimumsTable.created_at), asc(poolPendingMinimumsTable.id)).limit(50);
    for (const queue of groupPendingMinimumsByScope(pending)) {
      for (const row of queue) {
        const outcome = await payHelperFromPool({
          entryType: "guaranteed_minimum",
          amount: row.amount,
          requestId: row.request_id,
          helperId: row.helper_id,
          requestTitle: row.request_title,
          communityId: row.community_id,
          hubId: row.hub_id
        });
        if (outcome === "paid" || outcome === "duplicate") {
          await db.update(poolPendingMinimumsTable).set({ status: "paid", paid_at: /* @__PURE__ */ new Date() }).where(eq(poolPendingMinimumsTable.id, row.id));
          if (outcome === "paid") {
            paidCount++;
            logger.info(
              { request_id: row.request_id, helper_id: row.helper_id, amount: row.amount },
              "Backfilled guaranteed minimum from replenished pool"
            );
            const { sendPushToUser: sendPushToUser2 } = await Promise.resolve().then(() => (init_push(), push_exports));
            sendPushToUser2(row.helper_id, {
              title: "\u{1F499} Community Pool Thank-You (backfilled)",
              body: `The pool was replenished \u2014 $${row.amount.toFixed(2)} was just added to your Goodwill Fund for: "${row.request_title}".`,
              requestId: row.request_id,
              notifType: "wallet"
            }).catch((err) => logger.warn({ err, helper_id: row.helper_id }, "sendPushToUser (backfill): non-critical side effect failed \u2014 continuing"));
          }
        } else if (outcome === "insufficient") {
          break;
        }
      }
    }
    if (paidCount > 0) {
      const balance = await getPoolBalance();
      broadcast({ type: "pool_updated", payload: { balance } });
    }
  } catch (err) {
    logger.error({ err }, "processPendingMinimums failed");
  }
  return paidCount;
}
var LOW_BALANCE_ALERT_INTERVAL_MS = 6 * 60 * 60 * 1e3;
var _lastLowBalanceAlertAt = 0;
async function getPoolReservePolicy() {
  const defaults2 = { helpersCovered: 10, guaranteedHours: 4, safetyMultiplier: 1.25 };
  try {
    const rows = await db.select({ key: systemSettingsTable.key, value: systemSettingsTable.value }).from(systemSettingsTable).where(
      sql`${systemSettingsTable.key} IN ('pool_reserve_helpers_covered', 'pool_reserve_guaranteed_hours', 'pool_reserve_safety_multiplier')`
    );
    const byKey = Object.fromEntries(rows.map((row) => [row.key, row.value]));
    const helpersCovered = Number.parseFloat(byKey["pool_reserve_helpers_covered"] ?? "");
    const guaranteedHours = Number.parseFloat(byKey["pool_reserve_guaranteed_hours"] ?? "");
    const safetyMultiplier = Number.parseFloat(byKey["pool_reserve_safety_multiplier"] ?? "");
    return {
      helpersCovered: Number.isFinite(helpersCovered) && helpersCovered > 0 ? helpersCovered : defaults2.helpersCovered,
      guaranteedHours: Number.isFinite(guaranteedHours) && guaranteedHours > 0 ? guaranteedHours : defaults2.guaranteedHours,
      safetyMultiplier: Number.isFinite(safetyMultiplier) && safetyMultiplier >= 1 ? safetyMultiplier : defaults2.safetyMultiplier
    };
  } catch (err) {
    logger.error({ err }, "community-pool: reserve policy lookup failed \u2014 using defaults");
    return defaults2;
  }
}
async function getLowBalanceThreshold() {
  try {
    const [row] = await db.select({ value: systemSettingsTable.value }).from(systemSettingsTable).where(eq(systemSettingsTable.key, "pool_low_balance_threshold")).limit(1);
    const parsed = row ? parseFloat(row.value) : NaN;
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : 25;
  } catch {
    return 25;
  }
}
async function maybeAlertLowBalance() {
  try {
    const [balance, threshold] = await Promise.all([getPoolBalance(), getLowBalanceThreshold()]);
    if (toCents(balance) >= toCents(threshold)) return;
    if (Date.now() - _lastLowBalanceAlertAt < LOW_BALANCE_ALERT_INTERVAL_MS) return;
    _lastLowBalanceAlertAt = Date.now();
    logger.warn({ balance, threshold }, "COMMUNITY POOL LOW BALANCE \u2014 guaranteed minimums at risk");
    broadcast({ type: "pool_low_balance", payload: { balance, threshold } });
    const adminsResult = await db.select({ id: usersTable.id }).from(usersTable).where(eq(usersTable.is_admin, true));
    const admins = Array.isArray(adminsResult) ? adminsResult : [];
    const { sendPushToUser: sendPushToUser2 } = await Promise.resolve().then(() => (init_push(), push_exports));
    for (const admin of admins) {
      sendPushToUser2(admin.id, {
        title: "\u26A0\uFE0F Community Pool low balance",
        body: `Pool balance is $${balance.toFixed(2)} (threshold $${threshold.toFixed(2)}). Guaranteed minimums may be queued until the pool is replenished.`,
        notifType: "wallet"
      }).catch((err) => logger.warn({ err, admin_id: admin.id }, "sendPushToUser (admin low-balance): non-critical side effect failed \u2014 continuing"));
    }
  } catch (err) {
    logger.error({ err }, "maybeAlertLowBalance failed");
  }
}
