router8.patch("/admin/requests/:id/pledge-status", requireAuth, requireAdmin(), adminLimiter, async (req, res) => {
  const adminId = req.authenticatedUserId;
  const requestId = parseInt(String(req.params.id), 10);
  if (isNaN(requestId)) return res.status(400).json({ error: "Invalid request id" });
  const { pledge_status, reason } = req.body;
  if (pledge_status !== "active" && pledge_status !== "forgiven" && pledge_status !== "written_off" && pledge_status !== "defaulted") {
    return res.status(400).json({ error: "pledge_status must be 'active', 'forgiven', 'written_off', or 'defaulted'." });
  }
  const result = await db.transaction(async (tx) => {
    const [updated] = await tx.update(requestsTable).set({ pledge_status }).where(eq(requestsTable.id, requestId)).returning();
    if (!updated) return null;
    if (pledge_status === "forgiven" || pledge_status === "written_off") {
      await tx.update(scheduledPaymentsTable).set({ status: "cancelled" }).where(
        and(
          eq(scheduledPaymentsTable.request_id, requestId),
          eq(scheduledPaymentsTable.status, "pending")
        )
      );
    }
    return updated;
  });
  if (!result) return res.status(404).json({ error: "Request not found." });
  const actionLabel = pledge_status === "written_off" ? "wrote off" : pledge_status === "forgiven" ? "forgave" : pledge_status === "defaulted" ? "defaulted" : "restored";
  logger.info(
    {
      request_id: requestId,
      pledge_status,
      admin_id: adminId,
      pledge_amount: result.pledge_amount,
      pledge_paid: result.pledge_paid,
      reason: reason ?? null
    },
    `Admin ${actionLabel} pledge${reason ? ` \u2014 reason: ${reason}` : ""}`
  );
  return res.json(result);
});
