router14.get("/admin/nia-cost-alert", requireAuth, requireAdmin(), adminLimiter, async (_req, res) => {
  const DAILY_COST_THRESHOLD = parseFloat(process.env.NIA_DAILY_COST_THRESHOLD ?? "50.00");
  try {
    const response = await requestNia("/admin/costs?days=1", { method: "GET" });
    if (!response.ok) {
      return res.status(502).json({ error: "Failed to fetch cost data" });
    }
    const costData = await response.json();
    const todayCost = costData.daily?.[0]?.estimatedCostUsd ?? 0;
    const isAlert = todayCost > DAILY_COST_THRESHOLD;
    return res.json({
      alert: isAlert,
      threshold: DAILY_COST_THRESHOLD,
      todayCost,
      message: isAlert ? `Daily AI cost $${todayCost.toFixed(2)} exceeds threshold $${DAILY_COST_THRESHOLD.toFixed(2)}` : `Daily AI cost $${todayCost.toFixed(2)} within threshold $${DAILY_COST_THRESHOLD.toFixed(2)}`
    });
  } catch (err) {
    logger.error({ err }, "admin: failed to check cost alert");
    return res.status(500).json({ error: "Failed to check cost alert" });
  }
});
