// src/lib/url-safety.ts
import dns from "node:dns/promises";
import net from "node:net";
var MAX_REDIRECTS = 3;
function isDisallowedIp(ip) {
  const type = net.isIP(ip);
  if (type === 4) {
    const parts = ip.split(".").map(Number);
    const [a, b] = parts;
    if (a === 127) return true;
    if (a === 10) return true;
    if (a === 172 && b >= 16 && b <= 31) return true;
    if (a === 192 && b === 168) return true;
    if (a === 169 && b === 254) return true;
    if (a === 100 && b >= 64 && b <= 127) return true;
    if (a === 0) return true;
    return false;
  }
  if (type === 6) {
    const lower2 = ip.toLowerCase();
    if (lower2 === "::1") return true;
    if (lower2.startsWith("fe80:")) return true;
    if (lower2.startsWith("fc") || lower2.startsWith("fd")) return true;
    if (lower2.startsWith("::ffff:")) {
      const v4 = lower2.split(":").pop() ?? "";
      return net.isIP(v4) === 4 ? isDisallowedIp(v4) : true;
    }
    return false;
  }
  return true;
}
async function assertSafeExternalUrl(urlString) {
  let url2;
  try {
    url2 = new URL(urlString);
  } catch {
    throw new Error(`invalid URL: ${urlString}`);
  }
  if (url2.protocol !== "https:") {
    throw new Error(`unsafe URL scheme "${url2.protocol}" \u2014 only https is allowed`);
  }
  const hostname2 = url2.hostname.toLowerCase();
  if (hostname2 === "localhost" || hostname2.endsWith(".local") || hostname2.endsWith(".internal")) {
    throw new Error(`unsafe hostname: ${hostname2}`);
  }
  if (net.isIP(hostname2) && isDisallowedIp(hostname2)) {
    throw new Error(`unsafe IP literal in URL: ${hostname2}`);
  }
  let addresses;
  try {
    const results = await dns.lookup(hostname2, { all: true, verbatim: true });
    addresses = results.map((r2) => r2.address);
  } catch {
    throw new Error(`could not resolve hostname: ${hostname2}`);
  }
  if (addresses.length === 0) {
    throw new Error(`hostname resolved to no addresses: ${hostname2}`);
  }
  if (addresses.some(isDisallowedIp)) {
    throw new Error(`hostname resolves to a disallowed internal address: ${hostname2}`);
  }
  return url2;
}
async function safeFetch(urlString, init) {
  let current = urlString;
  for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
    await assertSafeExternalUrl(current);
    const resp = await fetch(current, { ...init, redirect: "manual" });
    if (resp.status >= 300 && resp.status < 400 && resp.headers.has("location")) {
      const next = new URL(resp.headers.get("location"), current).toString();
      current = next;
      continue;
    }
    return resp;
  }
  throw new Error("too many redirects while fetching URL");
}

