// src/lib/mediaCapabilities.ts
import { execFile as execFile2 } from "node:child_process";
import { mkdtemp as mkdtemp2, rm as rm2 } from "node:fs/promises";
import os2 from "node:os";
import path4 from "node:path";
import { promisify as promisify4 } from "node:util";
var execFileAsync2 = promisify4(execFile2);
var getToolPaths = () => ({
  ffmpeg: process.env["FFMPEG_PATH"]?.trim() || "ffmpeg",
  ffprobe: process.env["FFPROBE_PATH"]?.trim() || "ffprobe"
});
async function verifyExecutable(name2, executable) {
  try {
    await execFileAsync2(executable, ["-version"], { timeout: 1e4 });
  } catch (error40) {
    const detail = error40 instanceof Error ? error40.message : String(error40);
    throw new Error(
      `MEDIA_PLATFORM_V21 requires an executable FFmpeg/FFprobe toolchain. ${name2} "${executable}" could not be executed. Install the ffmpeg runtime package in the production image or set ${name2 === "ffmpeg" ? "FFMPEG_PATH" : "FFPROBE_PATH"} to an executable binary. Original error: ${detail}`
    );
  }
}
async function verifyMediaToolchain() {
  const { ffmpeg, ffprobe } = getToolPaths();
  await verifyExecutable("ffmpeg", ffmpeg);
  await verifyExecutable("ffprobe", ffprobe);
  const tempDir = await mkdtemp2(path4.join(os2.tmpdir(), "niakofa-media-toolchain-"));
  const output = path4.join(tempDir, "probe.mp4");
  try {
    await execFileAsync2(
      ffmpeg,
      [
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "color=c=black:s=16x16:d=0.1",
        "-frames:v",
        "1",
        "-pix_fmt",
        "yuv420p",
        "-y",
        output
      ],
      { timeout: 15e3 }
    );
    const { stdout } = await execFileAsync2(
      ffprobe,
      [
        "-v",
        "error",
        "-select_streams",
        "v:0",
        "-show_entries",
        "stream=width,height",
        "-of",
        "json",
        output
      ],
      { timeout: 15e3 }
    );
    const parsed = JSON.parse(String(stdout));
    const stream = parsed.streams?.[0];
    if (!stream?.width || !stream.height) {
      throw new Error("FFprobe did not return a usable video stream.");
    }
  } finally {
    await rm2(tempDir, { recursive: true, force: true });
  }
}

// src/lib/advance-pool-settlement-status.ts
init_stripe_esm_node();
init_drizzle_orm();
init_src();
init_ws_hub();
init_logger2();
init_worker_registry();
init_stripe_config();
async function advancePendingPoolSettlements(stripe7, options) {
  const pending = await db.select({
    id: communityPoolFinancialEventsTable.id,
    btId: communityPoolFinancialEventsTable.stripe_balance_transaction_id,
    ledgerId: communityPoolFinancialEventsTable.community_pool_ledger_id,
    userId: communityPoolFinancialEventsTable.user_id
  }).from(communityPoolFinancialEventsTable).where(
    and(
      inArray(communityPoolFinancialEventsTable.settlement_status, ["pending"]),
      isNotNull(communityPoolFinancialEventsTable.stripe_balance_transaction_id),
      eq(communityPoolFinancialEventsTable.stripe_verification_status, "verified")
    )
  ).limit(options?.limit ?? 50);
  let advanced = 0;
  for (const row of pending) {
    if (!row.btId) continue;
    try {
      const balanceTransaction = await stripe7.balanceTransactions.retrieve(row.btId);
      if (balanceTransaction.status !== "available") continue;
      await db.transaction(async (tx) => {
        await tx.update(communityPoolFinancialEventsTable).set({
          settlement_status: "available",
          available_on: balanceTransaction.available_on ? new Date(balanceTransaction.available_on * 1e3) : /* @__PURE__ */ new Date(),
          updated_at: /* @__PURE__ */ new Date()
        }).where(
          and(
            eq(communityPoolFinancialEventsTable.id, row.id),
            eq(communityPoolFinancialEventsTable.settlement_status, "pending")
          )
        );
        if (row.userId != null && row.ledgerId != null) {
          const availableOn = balanceTransaction.available_on ? new Date(balanceTransaction.available_on * 1e3).toISOString() : null;
          await tx.execute(sql`
            UPDATE transactions
            SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
              'stripe_verification_status', 'verified',
              'settlement_status', 'available',
              'available_on', CAST(${availableOn} AS text)
            )
            WHERE user_id = CAST(${row.userId} AS integer)
              AND type = 'pool_contribution'
              AND related_pool_ledger_id = CAST(${row.ledgerId} AS integer)
              AND COALESCE(metadata->>'kind', '') <> 'pool_contribution_refund'
          `);
        }
      });
      advanced += 1;
    } catch (err) {
      logger.warn({ err, financial_event_id: row.id }, "pool settlement advancement skipped");
    }
  }
  return { examined: pending.length, advanced };
}
function startPoolSettlementStatusWorker() {
  const secretKey = getStripeSecretKey();
  if (!secretKey) {
    logger.warn("pool-settlement-worker: Stripe not configured \u2014 advancement disabled");
    return () => void 0;
  }
  const stripe7 = new stripe_esm_node_default(secretKey, {
    apiVersion: "2024-06-20"
  });
  const intervalMs = 15 * 60 * 1e3;
  let running = false;
  const run = async () => {
    if (running) return;
    running = true;
    try {
      const result = await advancePendingPoolSettlements(stripe7);
      workerRan("pool-settlement", true);
      if (result.advanced > 0) {
        broadcast({ type: "pool_updated", payload: { balance: await getPoolBalance() } });
        logger.info(result, "pool-settlement-worker: advanced pending settlements");
      }
    } catch (err) {
      workerRan("pool-settlement", false);
      logger.warn({ err }, "pool-settlement-worker: run failed");
    } finally {
      running = false;
    }
  };
  const startupTimer = setTimeout(() => void run(), 3e4);
  const interval2 = setInterval(() => void run(), intervalMs);
  logger.info({ intervalMs }, "pool-settlement-worker: started");
  return () => {
    clearTimeout(startupTimer);
    clearInterval(interval2);
  };
}

